from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

def _dependency_solver(data, name_order, preference):
    packages = data["packages"]
    names = sorted(packages, reverse=(name_order == "descending"))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    best = None
    best_vector = None

    def acyclic(graph, nodes):
        active, done = set(), set()

        def visit(node):
            if node in active:
                return False
            if node in done:
                return True
            active.add(node)
            if any(not visit(other) for other in graph.get(node, [])):
                return False
            active.remove(node)
            done.add(node)
            return True

        return all(visit(node) for node in nodes)

    def search(chosen, requirements, graph):
        nonlocal best, best_vector
        pending = [name for name in requirements if name not in chosen]
        if not pending:
            if not acyclic(graph, chosen):
                return
            vector = tuple(chosen.get(name, -1) for name in names)
            if best_vector is None or (vector > best_vector if preference == "maximum"
                                       else vector < best_vector):
                best, best_vector = dict(chosen), vector
            return

        name = min(pending)
        low, high = requirements[name]
        rows = [row for row in packages[name]
                if low <= row["version"] <= high
                and row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        for row in rows:
            version = row["version"]
            deps = [dep for dep in row.get("deps", [])
                    if not dep.get("feature") or dep["feature"] in features]
            next_requirements = dict(requirements)
            next_graph = {key: list(value) for key, value in graph.items()}
            next_graph[name] = []
            valid = True
            for dep in deps:
                other = dep["name"]
                next_graph[name].append(other)
                lo, hi = dep["min"], dep["max"]
                if other in next_requirements:
                    old_lo, old_hi = next_requirements[other]
                    lo, hi = max(lo, old_lo), min(hi, old_hi)
                if lo > hi:
                    valid = False
                    break
                next_requirements[other] = (lo, hi)
                if other in chosen and not lo <= chosen[other] <= hi:
                    valid = False
                    break
            if valid:
                next_chosen = dict(chosen)
                next_chosen[name] = version
                search(next_chosen, next_requirements, next_graph)

    initial = {name: tuple(bounds) for name, bounds in data["roots"].items()}
    search({}, initial, {})
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _build_dependency(name_order, preference):
    return lambda data: _dependency_solver(data, name_order, preference)


def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (2 * numerator + denominator) // (2 * denominator)
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, data["rounding"])
            tax = rounded(net * event.get("tax_bp", 0), 10000, data["rounding"])
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}

    return solve


def _build_component_07():
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        options = [job for job in jobs if job["id"] not in blocked]
        best_ids = None
        best_value = None

        def feasible(subset):
            ids = {job["id"] for job in subset}
            if not mandatory.issubset(ids):
                return False
            counts = {}
            for job in subset:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            for group, bounds in quotas.items():
                lo, hi = bounds
                if not lo <= counts.get(group, 0) <= hi:
                    return False
            active_ends = []
            import heapq
            for job in sorted(subset, key=lambda row: (row["start"], row["end"])):
                while active_ends and active_ends[0] <= job["start"]:
                    heapq.heappop(active_ends)
                heapq.heappush(active_ends, job["end"])
                if len(active_ends) > 2:
                    return False
            return True

        if len(mandatory) > k or mandatory & blocked:
            return {"error": "impossible"}

        def enumerate_subsets(position, subset):
            nonlocal best_ids, best_value
            if len(subset) == k:
                if not feasible(subset):
                    return
                ids = tuple(sorted(job["id"] for job in subset))
                value = sum(job["value"] for job in subset)
                if best_value is None or value > best_value or (value == best_value and ids < best_ids):
                    best_value, best_ids = value, ids
                return
            if position == len(options) or len(subset) + len(options) - position < k:
                return
            job = options[position]
            enumerate_subsets(position + 1, subset + [job])
            enumerate_subsets(position + 1, subset)

        enumerate_subsets(0, [])
        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}

    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        indexes = {node: index for index, node in enumerate(required)}
        full_mask = (1 << len(required)) - 1
        mask = 1 << indexes[data["source"]] if data["source"] in indexes else 0
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start_state = (data["source"], mask, data["coupons"])
        distances = {start_state: data["start"]}
        queue = [(data["start"], data["source"], mask, data["coupons"])]
        while queue:
            time, node, visited, coupons = heapq.heappop(queue)
            state = (node, visited, coupons)
            if time != distances.get(state):
                continue
            if node == data["target"] and visited == full_mask:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                choices = [(edge["duration"], coupons)]
                if coupons:
                    choices.append((max(2, edge["duration"] - edge.get("discount", 0)), coupons - 1))
                for duration, remaining in choices:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    nxt = edge["v"]
                    new_mask = visited | (1 << indexes[nxt] if nxt in indexes else 0)
                    next_state = (nxt, new_mask, remaining)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, nxt, new_mask, remaining))
        return {"arrival": None}

    return solve


SOLVERS = {
    "component_01": _build_dependency("ascending", "maximum"),
    "component_02": _build_dependency("ascending", "minimum"),
    "component_03": _build_dependency("descending", "maximum"),
    "component_04": _build_dependency("descending", "minimum"),
    "component_05": _build_dependency("ascending", "maximum"),
    "component_06": _build_component_06(),
    "component_07": _build_component_07(),
    "component_08": _build_component_08(),
}
